using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Platform;
using PeopleHub.Application.Modules.Requests;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class AdvanceCancelTests
{
 class User(int? emp=6,params string[] grants):ICurrentUser{public string Email=>"advancecancel@example.local";public int? EmployeeId=>emp;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>grants.Contains(p);}
 class Db(DbContextOptions options):AppDbContext(options){public bool Fail;public override async Task<int> SaveChangesAsync(CancellationToken ct=default){var n=await base.SaveChangesAsync(ct);if(Fail)throw new InvalidOperationException("Fictional post-write failure");return n;}}
 static async Task<Db> Open(){var d=new Db(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.EnsureCreatedAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,25));return d;}
 static ApprovalService S(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,new AccessScope(d,u),u,a,new NotificationService(d,u,c),c,new WorkflowService(d,u,a),new DelegationService(d,u,a,c));}
 static async Task<int> Advance(AppDbContext d,int employeeId=6,decimal paid=0){var a=new AdvanceRequest{EmployeeId=employeeId,Amount=601.25m,Installments=3,StartYear=2030,StartMonth=1,Paid=paid,Status=RequestStatus.Approved,Reason="Fictional boundary evidence",AttachmentToken="PRIVATE-TOKEN",AttachmentName="PRIVATE-FILE",Comment="PRIVATE-DECISION",Route="PRIVATE-ROUTE"};d.Add(a);await d.SaveAsync();return a.Id;}
 [Fact]public async Task UnpaidApprovedAdvanceIsWithdrawnWithOneAuditAndStopsFutureDeductions(){await using var d=await Open();int id=await Advance(d);int audit=await d.Set<AuditLog>().CountAsync();await S(d,new User(8,Perm.AdvManage)).CancelUnpaidAdvanceAsync(id);var a=(await d.Set<AdvanceRequest>().FindAsync(id))!;Assert.Equal(RequestStatus.Cancelled,a.Status);Assert.Equal(0,a.Paid);Assert.False(a.DueIn(2031,1));Assert.Equal(audit+1,await d.Set<AuditLog>().CountAsync());Assert.Single(await d.Set<AuditLog>().Where(x=>x.Entity=="Advance"&&x.Action=="CancelUnpaid"&&x.EntityId==id.ToString()).ToListAsync());await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(8,Perm.AdvManage)).CancelUnpaidAdvanceAsync(id));}
 [Fact]public async Task PartlyRepaidPendingAndDeniedAdvancesAreRefusedWithoutChange(){await using var d=await Open();int part=await Advance(d,6,100);int pend=await Advance(d);var p=(await d.Set<AdvanceRequest>().FindAsync(pend))!;p.Status=RequestStatus.Pending;int ok=await Advance(d);await d.SaveAsync();int audit=await d.Set<AuditLog>().CountAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(8,Perm.AdvManage)).CancelUnpaidAdvanceAsync(part));await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(8,Perm.AdvManage)).CancelUnpaidAdvanceAsync(pend));await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(8)).CancelUnpaidAdvanceAsync(ok));await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(6)).CancelUnpaidAdvanceAsync(ok));Assert.Equal(RequestStatus.Approved,(await d.Set<AdvanceRequest>().FindAsync(part))!.Status);Assert.Equal(RequestStatus.Pending,(await d.Set<AdvanceRequest>().FindAsync(pend))!.Status);Assert.Equal(RequestStatus.Approved,(await d.Set<AdvanceRequest>().FindAsync(ok))!.Status);Assert.Equal(audit,await d.Set<AuditLog>().CountAsync());Assert.False(d.ChangeTracker.HasChanges());}
 [Fact]public async Task OpenPayrollRunWithInstallmentBlocksWithdrawalButFinalizedRunDoesNot(){await using var d=await Open();int id=await Advance(d);var run=new PayrollRun{Year=2030,Month=1,Status=PayrollStatus.Draft,CreatedBy="fictional"};d.Add(run);await d.SaveAsync();d.Add(new PayrollLine{RunId=run.Id,EmployeeId=6,AdvanceInstallment=200.42m});await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(8,Perm.AdvManage)).CancelUnpaidAdvanceAsync(id));Assert.Equal(RequestStatus.Approved,(await d.Set<AdvanceRequest>().FindAsync(id))!.Status);(await d.Set<PayrollRun>().FindAsync(run.Id))!.Status=PayrollStatus.Finalized;await d.SaveAsync();await S(d,new User(8,Perm.AdvManage)).CancelUnpaidAdvanceAsync(id);Assert.Equal(RequestStatus.Cancelled,(await d.Set<AdvanceRequest>().FindAsync(id))!.Status);}
 [Fact]public async Task WithdrawalPostSaveFailureAndOuterRollbackLeaveAdvanceApprovedThenRetryOnce(){await using var d=await Open();int id=await Advance(d);int audit=await d.Set<AuditLog>().CountAsync();d.Fail=true;await Assert.ThrowsAsync<InvalidOperationException>(()=>S(d,new User(8,Perm.AdvManage)).CancelUnpaidAdvanceAsync(id));d.Fail=false;Assert.Equal(RequestStatus.Approved,(await d.Set<AdvanceRequest>().FindAsync(id))!.Status);Assert.Equal(audit,await d.Set<AuditLog>().CountAsync());await Assert.ThrowsAsync<DomainException>(()=>d.AtomicAsync(async()=>{await S(d,new User(8,Perm.AdvManage)).CancelUnpaidAdvanceAsync(id);throw new DomainException("Fictional outer failure");}));Assert.Equal(RequestStatus.Approved,(await d.Set<AdvanceRequest>().FindAsync(id))!.Status);await S(d,new User(8,Perm.AdvManage)).CancelUnpaidAdvanceAsync(id);Assert.Equal(RequestStatus.Cancelled,(await d.Set<AdvanceRequest>().FindAsync(id))!.Status);Assert.Equal(audit+1,await d.Set<AuditLog>().CountAsync());}
}
